"""Minimal Anthropic Messages API -> AWS Bedrock proxy.

The NovaMind simulator engine talks to the Anthropic Messages API via the
`anthropic` SDK, which honours ANTHROPIC_BASE_URL. This sandbox has no
ANTHROPIC_API_KEY but does have AWS credentials with Bedrock Claude access,
so this process exposes /v1/messages locally and forwards to Bedrock.
"""

import json
import os
import sys
import threading
import time
import traceback
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

import boto3
from botocore.config import Config

REGION = os.environ.get("AWS_REGION", "us-east-2")
PORT = int(os.environ.get("PROXY_PORT", "8787"))
LOG_PATH = os.environ.get("PROXY_LOG", "/data/workspace/run-ceobench/proxy.log")

_cfg = Config(retries={"max_attempts": 10, "mode": "adaptive"}, read_timeout=900,
              connect_timeout=30, max_pool_connections=64)
_brt = boto3.client("bedrock-runtime", region_name=REGION, config=_cfg)

_KNOWN = [
    "us.anthropic.claude-haiku-4-5-20251001-v1:0",
    "us.anthropic.claude-sonnet-4-5-20250929-v1:0",
    "us.anthropic.claude-sonnet-4-6",
    "us.anthropic.claude-opus-4-5-20251101-v1:0",
    "us.anthropic.claude-3-haiku-20240307-v1:0",
]
_DEFAULT = "us.anthropic.claude-haiku-4-5-20251001-v1:0"

_lock = threading.Lock()
_stats = {"calls": 0, "errors": 0, "in_tok": 0, "out_tok": 0}


def _log(msg):
    try:
        with open(LOG_PATH, "a") as f:
            f.write(f"{time.strftime('%H:%M:%S')} {msg}\n")
    except Exception:
        pass


def resolve_model(name):
    """Map a requested Anthropic model id onto a Bedrock inference profile."""
    if not name:
        return _DEFAULT
    n = str(name)
    if n.startswith(("us.", "global.", "anthropic.")):
        return n
    exact = "us." + n if n.startswith("anthropic.") else "us.anthropic." + n
    if exact in _KNOWN:
        return exact
    low = n.lower()
    if "haiku" in low:
        return "us.anthropic.claude-haiku-4-5-20251001-v1:0"
    if "sonnet" in low:
        return "us.anthropic.claude-sonnet-4-5-20250929-v1:0"
    if "opus" in low:
        return "us.anthropic.claude-opus-4-5-20251101-v1:0"
    return exact if exact.startswith("us.anthropic.") else _DEFAULT


_STRIP = {"model", "stream", "metadata", "service_tier", "container",
          "mcp_servers", "betas", "anthropic_beta"}


def build_body(payload):
    body = {k: v for k, v in payload.items() if k not in _STRIP}
    body["anthropic_version"] = "bedrock-2023-05-31"
    body.setdefault("max_tokens", 1024)
    return body


def invoke(model_id, body, stream=False):
    fn = _brt.invoke_model_with_response_stream if stream else _brt.invoke_model
    last = None
    for attempt in range(6):
        try:
            return fn(modelId=model_id, body=json.dumps(body),
                      contentType="application/json", accept="application/json")
        except Exception as e:  # throttling / transient
            last = e
            msg = str(e)
            if "ThrottlingException" in msg or "TooManyRequests" in msg or "ServiceUnavailable" in msg or "ModelTimeout" in msg:
                time.sleep(min(2 ** attempt, 30))
                continue
            raise
    raise last


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):  # silence stderr spam
        pass

    def _send_json(self, code, obj):
        data = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def _err(self, code, etype, msg):
        with _lock:
            _stats["errors"] += 1
        _log(f"ERROR {code} {etype}: {msg[:400]}")
        self._send_json(code, {"type": "error", "error": {"type": etype, "message": msg}})

    def do_GET(self):
        if self.path.rstrip("/") in ("/health", "/_health"):
            with _lock:
                self._send_json(200, {"ok": True, **_stats})
        else:
            self._err(404, "not_found_error", f"no route {self.path}")

    def do_POST(self):
        try:
            n = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(n) if n else b"{}"
            payload = json.loads(raw or b"{}")
        except Exception as e:
            return self._err(400, "invalid_request_error", f"bad json: {e}")

        path = self.path.split("?")[0].rstrip("/")

        if path.endswith("/count_tokens"):
            approx = len(json.dumps(payload.get("messages", []))) // 4 + 8
            return self._send_json(200, {"input_tokens": approx})

        if not path.endswith("/messages"):
            return self._err(404, "not_found_error", f"no route {self.path}")

        model_id = resolve_model(payload.get("model"))
        stream = bool(payload.get("stream"))
        body = build_body(payload)

        try:
            if stream:
                return self._do_stream(model_id, body)
            resp = invoke(model_id, body, stream=False)
            out = json.loads(resp["body"].read())
            out.setdefault("model", payload.get("model") or model_id)
            with _lock:
                _stats["calls"] += 1
                u = out.get("usage") or {}
                _stats["in_tok"] += u.get("input_tokens", 0)
                _stats["out_tok"] += u.get("output_tokens", 0)
            return self._send_json(200, out)
        except Exception as e:
            tb = traceback.format_exc()
            _log(f"invoke failed model={model_id}\n{tb}")
            m = str(e)
            code = 429 if "Throttling" in m else 500
            return self._err(code, "api_error", m[:800])

    def _do_stream(self, model_id, body):
        resp = invoke(model_id, body, stream=True)
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("Connection", "keep-alive")
        self.send_header("Transfer-Encoding", "chunked")
        self.end_headers()

        def emit(ev):
            payload = f"event: {ev.get('type','message')}\ndata: {json.dumps(ev)}\n\n".encode()
            self.wfile.write(f"{len(payload):X}\r\n".encode() + payload + b"\r\n")
            self.wfile.flush()

        try:
            for event in resp["body"]:
                chunk = event.get("chunk")
                if not chunk:
                    continue
                ev = json.loads(chunk["bytes"])
                if ev.get("type") == "message_stop":
                    ev.pop("amazon-bedrock-invocationMetrics", None)
                emit(ev)
            self.wfile.write(b"0\r\n\r\n")
            self.wfile.flush()
            with _lock:
                _stats["calls"] += 1
        except Exception:
            _log("stream failed\n" + traceback.format_exc())
            try:
                emit({"type": "error", "error": {"type": "api_error", "message": "stream failed"}})
                self.wfile.write(b"0\r\n\r\n")
            except Exception:
                pass


def main():
    srv = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    srv.daemon_threads = True
    _log(f"proxy up on 127.0.0.1:{PORT} region={REGION}")
    print(f"proxy listening on 127.0.0.1:{PORT}", flush=True)
    srv.serve_forever()


if __name__ == "__main__":
    sys.exit(main())

